import{_ as t,o as s,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-9-deactivate-account/report3_spec.md","filePath":"feature/authentication/3-2-9-deactivate-account/report3_spec.md"}'),a={name:"feature/authentication/3-2-9-deactivate-account/report3_spec.md"};function i(r,e,l,c,d,h){return s(),o("div",null,[...e[0]||(e[0]=[n("<p><strong>3.2.9 Deactivate Account</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user activates &quot;Deactivate&quot; in the Danger Zone of the profile screen and confirms the dialog with their password, or, for an account with no password, with a one-time code sent to their email.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: USER who is signed in, either with a password or as an OAuth-only account with no password.</li><li><strong>Purpose</strong>: Let a user disable their own account (soft delete) after proving identity with the password or a one-time email code, and immediately cut off active sessions.</li><li><strong>Interface</strong>: Danger Zone section on the profile page with a confirmation dialog. Accounts with a password show a password field; accounts without one show a &quot;Send code&quot; button and, once sent, a six-digit code field.</li><li><strong>Data Processing</strong>: Resolves the caller from the Bearer access token, reads the refresh token cookie and the raw access token. Loads the user, verifies identity via the password or OTP branch, checks the caller does not own any ACTIVE agency, sets user.status = DEACTIVATED and saves, then blacklists the caller&#39;s access token and refresh token (best-effort) so active sessions are cut off immediately.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Deactivate Account (Profile, Danger Zone):</p><ul><li>A red-bordered &quot;Danger Zone&quot; card with a &quot;Deactivate&quot; button that opens the confirm dialog.</li><li>If the account has a password: the dialog shows a password input.</li><li>If the account has no password: the dialog shows a &quot;Send code&quot;/&quot;Resend code&quot; button followed by an OTP input.</li><li>Cancel and a destructive &quot;Confirm Deactivate&quot; button, disabled until the relevant field is non-empty or while the request is in flight.</li><li>On success the client clears the local session and returns to /login.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Bearer access token. Exactly one of password or otpCode, selected by the account&#39;s own state, not by which field the client sends.</li><li><strong>Input optional</strong>: both password and otpCode are optional at the request level; the service enforces which one is actually required and ignores the other. The refresh token cookie is optional.</li><li><strong>System data</strong>: userId (from token), user.passwordHash, user.status, deactivate OTP (Redis, TTL 10 min), agencies owned by the user and their status, the caller&#39;s raw access token and refresh token.</li><li><strong>Output</strong>: no payload, 200.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-22</strong>: Deactivation sets user.status = DEACTIVATED and blacklists outstanding tokens so active sessions are cut off. After the status update, the service blacklists the caller&#39;s access token and refresh token, each wrapped in a best-effort try/catch that ignores a malformed or absent token. A subsequent login or refresh is also rejected with 403 ACCOUNT_DEACTIVATED, but the blacklist call is what makes cut-off immediate rather than only on next refresh/expiry.</li><li><strong>BR-23</strong>: The last active OWNER of an Agency cannot self-deactivate. After identity is confirmed, the system checks for any Agency owned by the caller with status ACTIVE; if one exists -&gt; 409 AGENCY_OWNERSHIP_ACTIVE, account left unchanged.</li><li>Identity confirmation: no password on file -&gt; OTP branch (missing, expired, or mismatched code -&gt; 400 OTP_INVALID; a match deletes the key so it cannot be reused). Password on file -&gt; password branch (mismatch -&gt; 400 WRONG_CURRENT_PASSWORD). The field not used by the branch is ignored.</li><li>sendDeactivateOtp generates a 6-digit OTP (TTL 10 min) and emails it; there is no resend cooldown on this endpoint, unlike the analogous email-OTP and phone-OTP flows.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing or malformed access token -&gt; 401 INVALID_CREDENTIALS, toast <strong>MSG22</strong></li><li>password empty (password branch) -&gt; Display: <strong>MSG02</strong></li><li>otpCode empty or malformed (OTP branch) -&gt; Display: <strong>MSG02</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user opens the Danger Zone on the profile page and activates &quot;Deactivate&quot;.</li><li>The client resolves whether the account has a password and shows the matching field.</li><li>For an OAuth-only account, the user first clicks &quot;Send code&quot;; the system generates and emails a 6-digit OTP (TTL 10 min).</li><li>The user supplies the password or the OTP and confirms, with the Bearer header and, if present, the refresh cookie sent automatically.</li><li>The system resolves the caller and extracts the raw access token and refresh token.</li><li>The system loads the user and verifies the password or the OTP depending on whether a password is set.</li><li>The system checks for an ACTIVE agency owned by the user (BR-23); none found.</li><li>The system sets user.status = DEACTIVATED and saves.</li><li>The system blacklists the access token and, if present, the refresh token, ignoring failures on a malformed/absent token.</li><li>200 OK; the client clears the local session, redirects to /login, toast <strong>MSG91</strong>.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>5.a1: Missing or invalid access token -&gt; 401 INVALID_CREDENTIALS, toast <strong>MSG22</strong>. 5.a2: The user signs in again.</li><li>6.a1: Account referenced by the token no longer exists -&gt; 404 USER_NOT_FOUND, toast <strong>MSG38</strong>. 6.a2: The user signs in again with a valid account.</li><li>6.b1: Password branch, wrong password -&gt; 400 WRONG_CURRENT_PASSWORD, Display: <strong>MSG19</strong>. 6.b2: The user re-enters the password.</li><li>6.c1: OTP branch, code missing, expired, never requested, or mismatched -&gt; 400 OTP_INVALID, Display: <strong>MSG20</strong>. 6.c2: The user requests a new code and re-enters it.</li><li>7.a1: The user owns at least one ACTIVE agency (BR-23) -&gt; 409 AGENCY_OWNERSHIP_ACTIVE, toast <strong>MSG38</strong>. 7.a2: The user transfers agency ownership first; if the OTP branch was used, a new code must be requested before retrying.</li><li>9.a1: Access token malformed, expired, or absent at the blacklist step -&gt; caught and ignored; deactivation still succeeds. 9.a2: Same handling for a malformed/absent refresh cookie.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>user.status = DEACTIVATED; all related rows (agencies, workspace memberships, etc.) are kept — this is a soft delete.</li><li>The OTP, when the OTP branch was used, is consumed and cannot be reused.</li><li>The caller&#39;s access token and refresh token (if present) are blacklisted, so the currently active session is cut off immediately.</li><li>A subsequent login or refresh attempt is also rejected with 403 ACCOUNT_DEACTIVATED, independent of the blacklist.</li></ul>",14)])])}const p=t(a,[["render",i]]);export{g as __pageData,p as default};
